package com.jjm.oficina.controller;

import com.jjm.oficina.modelo.*;
import com.jjm.oficina.repositorio.*;
import com.jjm.oficina.servicio.PermisosService;
import com.jjm.oficina.servicio.ReportesDiariosService;
import com.jjm.oficina.servicio.AsistenciaAutomaticaService;
import jakarta.annotation.PostConstruct;
import org.springframework.http.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.*;
import java.util.*;

@RestController
@RequestMapping("/api/canales/proyectos/{proyecto}")
public class CanalProyectoController {
    private final JdbcTemplate jdbc;private final UsuarioRepository usuarios;private final ProyectoRepository proyectos;
    private final MiembroEquipoRepository miembros;private final MiembroProyectoRepository asignaciones;private final PermisosService permisos;
    private final ReportesDiariosService diarios;private final AsistenciaAutomaticaService asistencia;
    public CanalProyectoController(JdbcTemplate jdbc,UsuarioRepository usuarios,ProyectoRepository proyectos,MiembroEquipoRepository miembros,MiembroProyectoRepository asignaciones,PermisosService permisos,ReportesDiariosService diarios,AsistenciaAutomaticaService asistencia){this.jdbc=jdbc;this.usuarios=usuarios;this.proyectos=proyectos;this.miembros=miembros;this.asignaciones=asignaciones;this.permisos=permisos;this.diarios=diarios;this.asistencia=asistencia;}
    @PostConstruct public void preparar(){
        jdbc.execute("CREATE TABLE IF NOT EXISTS pmo_proyecto_carpetas (id BIGINT AUTO_INCREMENT PRIMARY KEY,id_proyecto INT NOT NULL,nombre VARCHAR(80) NOT NULL, UNIQUE KEY uk_carpeta_proyecto(id_proyecto,nombre)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        jdbc.execute("CREATE TABLE IF NOT EXISTS pmo_proyecto_archivos (id BIGINT AUTO_INCREMENT PRIMARY KEY,id_proyecto INT NOT NULL,carpeta VARCHAR(80) NOT NULL,nombre VARCHAR(180) NOT NULL,mime VARCHAR(120) NOT NULL,contenido MEDIUMBLOB NOT NULL,bytes INT NOT NULL,sha256 CHAR(64) NOT NULL,id_usuario INT NOT NULL,fecha DATETIME NOT NULL,eliminado BOOLEAN NOT NULL DEFAULT FALSE,KEY idx_archivos_proyecto(id_proyecto,eliminado),KEY idx_archivos_firma(id_proyecto,sha256)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        jdbc.execute("CREATE TABLE IF NOT EXISTS pmo_calendario_proyecto (id_proyecto INT NOT NULL,fecha DATE NOT NULL,laboral BOOLEAN NOT NULL,motivo VARCHAR(250) NOT NULL,id_usuario INT NOT NULL,actualizado DATETIME NOT NULL,PRIMARY KEY(id_proyecto,fecha)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    }
    private boolean admin(Usuario u){return permisos.esSuperadministrador(u)||permisos.esAdministradorBase(u);}
    private boolean consulta(Usuario u){String r=String.valueOf(u.getRol()==null?"":u.getRol().getNombre()).toLowerCase(Locale.ROOT);return Set.of("directivo","directivo escolar","supervisor").contains(r);}
    private boolean consultaTodos(Usuario u){return admin(u)||consulta(u)||PermisosService.esAsesorEmpresarial(u);}
    private boolean asignado(Integer proyecto,Usuario u){MiembroEquipo m=miembros.findByUsuarioId(u.getId()).orElse(null);return m!=null&&asignaciones.existsByIdProyectoAndIdMiembro(proyecto,m.getId());}
    private boolean puedeEscribir(Integer proyecto,Usuario u){return !consulta(u)&&(admin(u)||asignado(proyecto,u));}
    private Usuario acceso(Integer proyecto,Integer id){
        Usuario u=id==null?null:usuarios.findById(id).orElse(null);if(u==null||!"Activo".equalsIgnoreCase(u.getEstado()))throw fallo(401,"Inicia sesión para abrir este canal.");
        if(u.getRol()!=null&&"Empresa".equalsIgnoreCase(u.getRol().getNombre()))throw fallo(403,"Tu cuenta utiliza el portal empresarial.");
        if(!proyectos.existsById(proyecto))throw fallo(404,"El proyecto no existe.");
        if(!admin(u)&&!PermisosService.esAsesorEmpresarial(u)&&!asignado(proyecto,u))throw fallo(403,"No estás asignado a este proyecto.");return u;
    }
    private void escritura(Integer proyecto,Usuario u){if(!puedeEscribir(proyecto,u))throw fallo(403,"Tu acceso a este canal es de consulta.");}
    private static ResponseStatusException fallo(int estado,String texto){return new ResponseStatusException(HttpStatus.valueOf(estado),texto);}
    @ExceptionHandler(ResponseStatusException.class) public ResponseEntity<Map<String,Object>> error(ResponseStatusException e){return ResponseEntity.status(e.getStatusCode()).body(Map.of("mensaje",Objects.toString(e.getReason(),"No se pudo completar la acción.")));}
    @GetMapping public Map<String,Object> canal(@PathVariable Integer proyecto,@RequestHeader(value="X-Usuario-Id",required=false) Integer id){Usuario u=acceso(proyecto,id);return Map.of("puedeGestionar",admin(u),"puedeSubir",puedeEscribir(proyecto,u),"puedeRevisar",admin(u),"puedeConsultarTodos",consultaTodos(u),"inicioReportes",diarios.inicio(),"horaLimite","17:00");}
    @GetMapping("/carpetas") public Map<String,Object> carpetas(@PathVariable Integer proyecto,@RequestHeader(value="X-Usuario-Id",required=false) Integer id){acceso(proyecto,id);Set<String> nombres=new LinkedHashSet<>(List.of("Proyecto","Manuales","PMBOK"));jdbc.queryForList("SELECT nombre FROM pmo_proyecto_carpetas WHERE id_proyecto=? ORDER BY nombre",proyecto).forEach(r->nombres.add(String.valueOf(r.get("nombre"))));return Map.of("carpetas",nombres);}
    public record Carpeta(String nombre){}
    @PostMapping("/carpetas") public Map<String,Object> crearCarpeta(@PathVariable Integer proyecto,@RequestBody Carpeta entrada,@RequestHeader(value="X-Usuario-Id",required=false) Integer id){Usuario u=acceso(proyecto,id);if(!admin(u))throw fallo(403,"Solo administración puede crear carpetas.");String nombre=limpiar(entrada.nombre(),80);if(nombre.isBlank())throw fallo(400,"Escribe el nombre de la carpeta.");jdbc.update("INSERT IGNORE INTO pmo_proyecto_carpetas(id_proyecto,nombre) VALUES(?,?)",proyecto,nombre);return Map.of("estado","correcto");}
    private String carpeta(Integer proyecto,String carpeta){String c=limpiar(carpeta,80);if(List.of("Proyecto","Manuales","PMBOK").contains(c)||!jdbc.queryForList("SELECT id FROM pmo_proyecto_carpetas WHERE id_proyecto=? AND nombre=?",proyecto,c).isEmpty())return c;throw fallo(400,"Selecciona una carpeta del proyecto.");}
    @GetMapping("/archivos") public Map<String,Object> archivos(@PathVariable Integer proyecto,@RequestParam(defaultValue="Proyecto") String carpeta,@RequestHeader(value="X-Usuario-Id",required=false) Integer id){Usuario u=acceso(proyecto,id);List<Map<String,Object>> datos=jdbc.queryForList("SELECT a.id,a.nombre,a.carpeta,a.mime,a.bytes,a.fecha,a.id_usuario AS idUsuario,u.nombre AS autor FROM pmo_proyecto_archivos a JOIN usuarios u ON u.id_usuario=a.id_usuario WHERE a.id_proyecto=? AND a.carpeta=? AND a.eliminado=FALSE ORDER BY a.fecha DESC LIMIT 500",proyecto,carpeta(proyecto,carpeta));datos.forEach(r->r.put("puedeRetirar",admin(u)||(puedeEscribir(proyecto,u)&&Objects.equals(((Number)r.get("idUsuario")).intValue(),id))));return Map.of("archivos",datos);}
    public record Archivo(String carpeta,String nombre,String base64){}
    @PostMapping("/archivos") public Map<String,Object> subir(@PathVariable Integer proyecto,@RequestBody Archivo entrada,@RequestHeader(value="X-Usuario-Id",required=false) Integer id) throws Exception {
        Usuario u=acceso(proyecto,id);escritura(proyecto,u);String nombre=limpiar(entrada.nombre(),180).replaceAll("[\\\\/:*?\"<>|]","_");String c=carpeta(proyecto,entrada.carpeta());
        if(nombre.isBlank()||entrada.base64()==null||entrada.base64().length()>5_592_410)throw fallo(400,"Cada archivo admite hasta 4 MB.");
        byte[] bytes;try{bytes=Base64.getDecoder().decode(entrada.base64());}catch(IllegalArgumentException e){throw fallo(400,"El archivo no se pudo leer.");}
        if(bytes.length==0||bytes.length>4*1024*1024)throw fallo(400,"Cada archivo admite hasta 4 MB.");
        String extension=nombre.contains(".")?nombre.substring(nombre.lastIndexOf('.')+1).toLowerCase(Locale.ROOT):"";
        Map<String,String> tipos=Map.of("pdf","application/pdf","docx","application/vnd.openxmlformats-officedocument.wordprocessingml.document","xlsx","application/vnd.openxmlformats-officedocument.spreadsheetml.sheet","pptx","application/vnd.openxmlformats-officedocument.presentationml.presentation","png","image/png","jpg","image/jpeg","jpeg","image/jpeg","webp","image/webp","txt","text/plain","csv","text/csv");
        if(!tipos.containsKey(extension))throw fallo(400,"Admite PDF, DOCX, XLSX, PPTX, PNG, JPG, WebP, TXT y CSV.");
        if(extension.equals("pdf")&&!new String(bytes,0,Math.min(5,bytes.length),StandardCharsets.US_ASCII).equals("%PDF-"))throw fallo(400,"El contenido no corresponde a un PDF.");
        if(Set.of("docx","xlsx","pptx").contains(extension)&&(bytes.length<4||bytes[0]!='P'||bytes[1]!='K'))throw fallo(400,"El contenido no corresponde a un documento de Office.");
        String sha=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));
        List<Map<String,Object>> igual=jdbc.queryForList("SELECT id,carpeta FROM pmo_proyecto_archivos WHERE id_proyecto=? AND sha256=? AND eliminado=FALSE LIMIT 1",proyecto,sha);
        if(!igual.isEmpty())return Map.of("estado","correcto","existente",true,"carpeta",igual.getFirst().get("carpeta"));
        jdbc.update("INSERT INTO pmo_proyecto_archivos(id_proyecto,carpeta,nombre,mime,contenido,bytes,sha256,id_usuario,fecha) VALUES(?,?,?,?,?,?,?,?,?)",proyecto,c,nombre,tipos.get(extension),bytes,bytes.length,sha,id,LocalDateTime.now(ZoneId.of("America/Mexico_City")));return Map.of("estado","correcto","existente",false);
    }
    @GetMapping("/archivos/{archivo}") public ResponseEntity<byte[]> descargar(@PathVariable Integer proyecto,@PathVariable Long archivo,@RequestHeader(value="X-Usuario-Id",required=false) Integer id){acceso(proyecto,id);List<Map<String,Object>> rs=jdbc.queryForList("SELECT nombre,mime,contenido FROM pmo_proyecto_archivos WHERE id=? AND id_proyecto=? AND eliminado=FALSE",archivo,proyecto);if(rs.isEmpty())throw fallo(404,"El archivo no existe en este proyecto.");Map<String,Object> r=rs.getFirst();return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(String.valueOf(r.get("nombre")),StandardCharsets.UTF_8).build().toString()).header("X-Content-Type-Options","nosniff").header(HttpHeaders.CACHE_CONTROL,"no-store").contentType(MediaType.APPLICATION_OCTET_STREAM).body((byte[])r.get("contenido"));}
    @DeleteMapping("/archivos/{archivo}") public Map<String,Object> retirar(@PathVariable Integer proyecto,@PathVariable Long archivo,@RequestHeader(value="X-Usuario-Id",required=false) Integer id){Usuario u=acceso(proyecto,id);escritura(proyecto,u);int cambio=admin(u)?jdbc.update("UPDATE pmo_proyecto_archivos SET eliminado=TRUE WHERE id=? AND id_proyecto=? AND eliminado=FALSE",archivo,proyecto):jdbc.update("UPDATE pmo_proyecto_archivos SET eliminado=TRUE WHERE id=? AND id_proyecto=? AND id_usuario=? AND eliminado=FALSE",archivo,proyecto,id);if(cambio==0)throw fallo(404,"No se encontró un archivo tuyo para retirar.");return Map.of("estado","correcto","mensaje","El archivo se conserva en la base como retirado.");}
    @GetMapping("/calendario") public Map<String,Object> calendario(@PathVariable Integer proyecto,@RequestParam String mes,@RequestHeader(value="X-Usuario-Id",required=false) Integer id){acceso(proyecto,id);YearMonth m=mes(mes);return Map.of("dias",jdbc.queryForList("SELECT fecha,laboral,motivo FROM pmo_calendario_proyecto WHERE id_proyecto=? AND fecha BETWEEN ? AND ? ORDER BY fecha",proyecto,m.atDay(1),m.atEndOfMonth()));}
    public record Dia(String fecha,Boolean laboral,String motivo){}
    @PutMapping("/calendario") public Map<String,Object> guardarDia(@PathVariable Integer proyecto,@RequestBody Dia dia,@RequestHeader(value="X-Usuario-Id",required=false) Integer id){Usuario u=acceso(proyecto,id);if(!admin(u))throw fallo(403,"Solo administración puede marcar el calendario.");LocalDate fecha;try{fecha=LocalDate.parse(dia.fecha());}catch(Exception e){throw fallo(400,"Fecha inválida.");}if(dia.laboral()==null||fecha.getYear()<2000||fecha.getYear()>2100)throw fallo(400,"Día inválido.");jdbc.update("INSERT INTO pmo_calendario_proyecto(id_proyecto,fecha,laboral,motivo,id_usuario,actualizado) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE laboral=VALUES(laboral),motivo=VALUES(motivo),id_usuario=VALUES(id_usuario),actualizado=VALUES(actualizado)",proyecto,fecha,dia.laboral(),limpiar(dia.motivo(),250),id,LocalDateTime.now(ZoneId.of("America/Mexico_City")));return Map.of("estado","correcto");}
    static YearMonth mes(String mes){try{YearMonth r=YearMonth.parse(mes);if(r.getYear()<2000||r.getYear()>2100)throw new IllegalArgumentException();return r;}catch(Exception e){throw fallo(400,"Selecciona un mes válido.");}}
    public record Reporte(String fecha,String actividad,String resultado,String evidencia,Long idArchivo,String fase,Double horas,String bloqueos){}
    @GetMapping("/habilitacion-reporte") public Map<String,Object> habilitacion(@PathVariable Integer proyecto,@RequestParam String fecha,@RequestHeader(value="X-Usuario-Id",required=false) Integer id){Usuario u=acceso(proyecto,id);Map<String,Object> respuesta=new java.util.LinkedHashMap<>(AsistenciaAutomaticaService.esAlumno(u)?asistencia.habilitacionReporte(id,fechaReporte(fecha)):Map.of("habilitado",true,"mensaje","Disponible para tu rol."));respuesta.put("entregaDiaria",diarios.entregaDelDia(id,fechaReporte(fecha)));return respuesta;}
    private static LocalDate fechaReporte(String fecha){try{return LocalDate.parse(fecha);}catch(Exception e){throw fallo(400,"Selecciona una fecha válida de reporte.");}}
    @PostMapping("/reportes-diarios") public Map<String,Object> enviarReporte(@PathVariable Integer proyecto,@RequestBody Reporte r,@RequestHeader(value="X-Usuario-Id",required=false) Integer id){Usuario u=acceso(proyecto,id);escritura(proyecto,u);if(AsistenciaAutomaticaService.esAlumno(u)){Map<String,Object> puerta=asistencia.habilitacionReporte(id,fechaReporte(r.fecha()));if(!Boolean.TRUE.equals(puerta.get("habilitado")))throw fallo(409,String.valueOf(puerta.get("mensaje")));}return diarios.guardar(proyecto,id,r);}
    @GetMapping("/reportes-diarios") public Map<String,Object> reportes(@PathVariable Integer proyecto,@RequestParam String mes,@RequestHeader(value="X-Usuario-Id",required=false) Integer id){Usuario u=acceso(proyecto,id);YearMonth m=mes(mes);return Map.of("reportes",diarios.listar(proyecto,id,consultaTodos(u),m),"puedeRevisar",admin(u));}
    @GetMapping("/reportes-diarios/{reporte}/historial") public Map<String,Object> historial(@PathVariable Integer proyecto,@PathVariable Long reporte,@RequestHeader(value="X-Usuario-Id",required=false) Integer id){Usuario u=acceso(proyecto,id);List<Map<String,Object>> propietario=jdbc.queryForList("SELECT id_usuario FROM pmo_reportes_actividad WHERE id=? AND id_proyecto=?",reporte,proyecto);if(propietario.isEmpty())throw fallo(404,"No existe el reporte en este proyecto.");if(!consultaTodos(u)&&((Number)propietario.getFirst().get("id_usuario")).intValue()!=id)throw fallo(403,"Solo puedes consultar el historial de tu reporte.");return Map.of("historial",jdbc.queryForList("SELECT h.accion,h.detalle,h.fecha,CONCAT_WS(' ',u.nombre,u.apellido_paterno,u.apellido_materno) AS autor FROM pmo_reporte_diario_historial h JOIN usuarios u ON u.id_usuario=h.id_usuario WHERE h.id_reporte=? ORDER BY h.id",reporte));}
    public record Revision(String estado,String observaciones){}
    @PutMapping("/reportes-diarios/{reporte}") public Map<String,Object> revisar(@PathVariable Integer proyecto,@PathVariable Long reporte,@RequestBody Revision r,@RequestHeader(value="X-Usuario-Id",required=false) Integer id){Usuario u=acceso(proyecto,id);if(!admin(u))throw fallo(403,"Solo administración puede revisar entregas.");diarios.revisar(proyecto,reporte,id,r.estado(),r.observaciones());return Map.of("estado","correcto");}
    @GetMapping("/formatos") public Map<String,Object> formatos(@PathVariable Integer proyecto,@RequestParam String mes,@RequestParam Integer miembro,@RequestHeader(value="X-Usuario-Id",required=false) Integer id){Usuario u=acceso(proyecto,id);YearMonth m=mes(mes);MiembroEquipo alumno=miembros.findById(miembro).orElse(null);if(alumno==null||alumno.getUsuario()==null||!asignaciones.existsByIdProyectoAndIdMiembro(proyecto,miembro))throw fallo(404,"El alumno no está asignado a este proyecto.");if(!consultaTodos(u)&&!Objects.equals(alumno.getUsuario().getId(),id))throw fallo(403,"Solo puedes generar tu reporte y tu asistencia.");
        List<Map<String,Object>> academic=jdbc.queryForList("SELECT matricula,universidad,carrera,fecha_inicio AS fechaInicio,fecha_fin AS fechaFin,horas_comprometidas AS horasComprometidas FROM datos_academicos_usuario WHERE id_usuario=?",alumno.getUsuario().getId());
        List<Map<String,Object>> horas=jdbc.queryForList("SELECT fecha,hora_entrada AS horaEntrada,hora_salida AS horaSalida,horas_trabajadas AS horasTrabajadas,estado_validacion AS estadoValidacion,incidente,descripcion FROM registros_horas WHERE id_miembro=? AND fecha BETWEEN ? AND ? ORDER BY fecha,hora_entrada",miembro,m.atDay(1),m.atEndOfMonth());
        Proyecto p=proyectos.findById(proyecto).orElseThrow();Map<String,Object> datos=new LinkedHashMap<>(academic.isEmpty()?Map.of():academic.getFirst());datos.put("nombreCompleto",Objects.toString(alumno.getNombreCompleto(),alumno.getUsuario().getNombre()));
        Number corte=jdbc.queryForObject("SELECT COALESCE(SUM(horas_trabajadas),0) FROM registros_horas WHERE id_miembro=? AND estado_validacion='Aprobado' AND fecha BETWEEN '2026-09-01' AND '2026-10-13' AND WEEKDAY(fecha)<5",Number.class,miembro);
        return Map.of("datos",datos,"registros",horas,"horasAprobadasCorte",corte==null?0:corte,"actividades",diarios.listar(proyecto,alumno.getUsuario().getId(),false,m),"calendario",calendario(proyecto,mes,id).get("dias"),"proyecto",Map.of("id",proyecto,"nombre",Objects.toString(p.getNombre(),"Proyecto"),"codigo",Objects.toString(p.getCodigo(),"")));
    }
    static String limpiar(String s,int max){String r=Objects.toString(s,"").replaceAll("[\\p{Cntrl}&&[^\\n\\t]]","").trim();if(r.length()>max)throw fallo(400,"El texto es demasiado largo.");return r;}
}
